with src as (select *, round(age * 1.1, 2) as age_adjusted from customers where signup_date < '2024-02-24' and signup_date between '2023-07-21' and '2025-01-19'), agg as (select case when year(signup_date) < 2024 then 'before_2024' when year(signup_date) = 2024 then '2024' else 'after_2024' end as signup_cohort, round(avg(age_adjusted), 2) as avg_age_adjusted, min(age) as min_age from src group by case when year(signup_date) < 2024 then 'before_2024' when year(signup_date) = 2024 then '2024' else 'after_2024' end) select * from agg order by min_age desc, signup_cohort limit 5
